def _validate_braces(self):
    '''Validate that all fields are properly enclosed in matching braces.'''
    i = 0
    while i < len(self._format):
        if self._format[i] == '{':
            # Check if next char is also { (escaped brace)
            if i + 1 < len(self._format) and self._format[i+1] == '{':
                # Find the matching }}
                j = self._format.find('}}', i + 2)
                if j == -1:
                    raise ValueError("unclosed escaped brace in pattern: %r" % self._format)
                i = j + 2  # Skip past }}
                continue

            # This is a potential field start - find the matching }
            j = self._format.find('}', i + 1)
            if j == -1:
                raise ValueError("unclosed field in pattern: %r" % self._format)

            # Move past the closing brace
            i = j + 1
            # If there's another } immediately after, skip it too (escaped })
            if i < len(self._format) and self._format[i] == '}':
                i += 1
        elif self._format[i] == '}':
            # Check if next char is also } (escaped brace)
            if i + 1 < len(self._format) and self._format[i+1] == '}':
                i += 2  # Skip }}
            else:
                raise ValueError("orphaned closing brace in pattern: %r" % self._format)
        else:
            i += 1

